import 'package:path/path.dart' as path;

String fileNameCheck(String fileName) {
  final normalizedPath = normalize(fileName);

  // Check that there are at least two parts in the filename (e.g., "file.exe")
  var splitParts = normalizedPath.split(path.separator).reversed.toList();
  return !(splitParts.length > 1 &&
      ['EXE', 'DLL'].contains(splitParts[0].toUpperCase()) && !normalizedPath.startsWith('/'));
}
```

